<link rel="stylesheet" href="<?=asset('css/views/pacientes.css')?>"><div class="page-heading"><div><span class="eyebrow">Expediente clínico</span><h1>🐾 <?=e($patient['nombre']?:'Paciente')?></h1><p><?=e($patient['especie'])?><?=!empty($patient['raza'])?' · '.e($patient['raza']):''?> · <?=e($patient['sexo']??'—')?></p></div><a class="btn btn-secondary" href="<?=url('/pacientes')?>">← Pacientes</a></div><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="metric-grid"><div class="metric-card"><span>Peso actual</span><strong><?= $patient['peso_actual']!==null?e($patient['peso_actual']).' kg':'—'?></strong></div><div class="metric-card"><span>Propietario</span><strong><?=e(trim(($patient['propietario_nombres']??'').' '.($patient['propietario_apellidos']??''))?:'—')?></strong></div><div class="metric-card"><span>Nacimiento</span><strong><?=e($patient['fecha_nacimiento']??'—')?></strong></div><div class="metric-card"><span>Color</span><strong><?=e($patient['color']??'—')?></strong></div></div><section class="card mb-1"><div class="card-header"><div><h2>Evolución de peso</h2></div><?php if(can('pacientes.editar')):?><button class="btn btn-primary" data-modal-open="weight-add">＋ Peso</button><?php endif;?></div><div class="table-wrap"><table class="modern-table"><thead><tr><th>Fecha</th><th>Peso</th><th>Origen</th><th>Registrado por</th></tr></thead><tbody><?php foreach($weights as $w):?><tr><td><?=e($w['fecha_registro'])?></td><td><?=e($w['peso_kg'])?> kg</td><td><?=e($w['origen']??'—')?></td><td><?=e($w['registrado_por_nombre'])?></td></tr><?php endforeach;?></tbody></table></div></section><section class="card"><div class="card-header"><div><h2>Historial clínico</h2><p>Consultas, vacunas, desparasitación, hospitalización, laboratorio y cirugía.</p></div></div><div class="stack"><?php foreach($timeline as $e):?><article class="soft-panel"><div class="inline-actions"><strong><?=e($e['tipo_nombre']??$e['titulo']??'Evento clínico')?></strong><span class="status-badge status-neutral"><?=e(date('d/m/Y H:i',strtotime($e['fecha_evento'])))?></span></div><p><?=e($e['titulo']??'')?></p><?php if(($e['tipo_codigo']??'')==='HOSPITALIZACION'):?><a class="btn btn-secondary btn-sm" href="<?=url('/hospitalizaciones/'.$e['id'])?>">Ver hospitalización</a><?php endif;?></article><?php endforeach;?></div></section><div class="modal" id="weight-add"><div class="modal-backdrop"></div><div class="modal-dialog"><div class="modal-header"><h2>Registrar peso</h2><button data-modal-close class="modal-close">×</button></div><form method="POST" action="<?=url('/pacientes/'.$patient['id'].'/peso')?>"><?=csrf_field()?><div class="modal-body form-grid"><label><span>Peso kg</span><input type="number" step="0.001" min="0.001" name="peso_kg" required></label><label><span>Observación</span><input name="observacion"></label></div><div class="modal-footer"><button class="btn btn-primary">Guardar</button></div></form></div></div>
